-- GalaxHub IconEngine: Pure Lua 24x24 PNG Generator with Alpha Mask Color Tinting
local IconEngine = {
    Masks = {},
    Cache = {},
    Width = 24,
    Height = 24,
}

-- Base64 lookup
local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local b64lut = {}
for i = 1, #b64chars do
    b64lut[string.byte(b64chars, i)] = i - 1
end

local function base64Decode(str)
    local out = {}
    local len = #str
    local i = 1
    while i <= len do
        local c1 = b64lut[string.byte(str, i)] or 0
        local c2 = b64lut[string.byte(str, i + 1)] or 0
        local c3 = b64lut[string.byte(str, i + 2)] or 0
        local c4 = b64lut[string.byte(str, i + 3)] or 0

        out[#out + 1] = string.char(bit32.bor(bit32.lshift(c1, 2), bit32.rshift(c2, 4)))
        if string.sub(str, i + 2, i + 2) ~= "=" then
            out[#out + 1] = string.char(bit32.bor(bit32.band(bit32.lshift(c2, 4), 0xF0), bit32.rshift(c3, 2)))
        end
        if string.sub(str, i + 3, i + 3) ~= "=" then
            out[#out + 1] = string.char(bit32.bor(bit32.band(bit32.lshift(c3, 6), 0xC0), c4))
        end
        i = i + 4
    end
    return table.concat(out)
end

-- Precomputed CRC32 Table
local crcTable = {}
for i = 0, 255 do
    local rem = i
    for _ = 1, 8 do
        if bit32.band(rem, 1) == 1 then
            rem = bit32.bxor(bit32.rshift(rem, 1), 0xEDB88320)
        else
            rem = bit32.rshift(rem, 1)
        end
    end
    crcTable[i] = rem
end

local function crc32(str)
    local crc = 0xFFFFFFFF
    for i = 1, #str do
        local byte = string.byte(str, i)
        crc = bit32.bxor(bit32.rshift(crc, 8), crcTable[bit32.bxor(bit32.band(crc, 0xFF), byte)])
    end
    return bit32.bxor(crc, 0xFFFFFFFF)
end

local function adler32(str)
    local a, b = 1, 0
    for i = 1, #str do
        a = (a + string.byte(str, i)) % 65521
        b = (b + a) % 65521
    end
    return (b * 65536) + a
end

local function u32be(n)
    return string.char(
        bit32.band(bit32.rshift(n, 24), 0xFF),
        bit32.band(bit32.rshift(n, 16), 0xFF),
        bit32.band(bit32.rshift(n, 8), 0xFF),
        bit32.band(n, 0xFF)
    )
end

local function u16le(n)
    return string.char(bit32.band(n, 0xFF), bit32.band(bit32.rshift(n, 8), 0xFF))
end

function IconEngine:BuildPng(r, g, b, rawMask)
    local scanlines = {}
    local idx = 1
    for y = 1, 24 do
        scanlines[#scanlines + 1] = "\0"
        for x = 1, 24 do
            local a = string.byte(rawMask, idx) or 0
            idx = idx + 1
            scanlines[#scanlines + 1] = string.char(r, g, b, a)
        end
    end
    local rawData = table.concat(scanlines)
    local dataLen = #rawData

    local zlibHeader = "\120\1"
    local bfinal = "\1"
    local lenBytes = u16le(dataLen)
    local nlenBytes = u16le(bit32.bxor(dataLen, 0xFFFF))
    local checksum = u32be(adler32(rawData))
    local idatPayload = zlibHeader .. bfinal .. lenBytes .. nlenBytes .. rawData .. checksum

    local sig = "\137PNG\r\n\26\n"
    local ihdrData = u32be(24) .. u32be(24) .. "\8\6\0\0\0"
    local ihdrChunk = u32be(#ihdrData) .. "IHDR" .. ihdrData .. u32be(crc32("IHDR" .. ihdrData))
    local idatChunk = u32be(#idatPayload) .. "IDAT" .. idatPayload .. u32be(crc32("IDAT" .. idatPayload))
    local iendChunk = u32be(0) .. "IEND" .. u32be(crc32("IEND"))

    return sig .. ihdrChunk .. idatChunk .. iendChunk
end

function IconEngine:RegisterMask(name, base64String)
    name = tostring(name):lower()
    self.Masks[name] = base64Decode(base64String)
end

function IconEngine:Get(name, color3)
    name = tostring(name or ""):lower()
    local mask = self.Masks[name]
    if not mask then return nil end

    local r = math.floor((color3 and color3.R or 1) * 255 + 0.5)
    local g = math.floor((color3 and color3.G or 1) * 255 + 0.5)
    local b = math.floor((color3 and color3.B or 1) * 255 + 0.5)
    local key = name .. "_" .. string.format("%02X%02X%02X", r, g, b)

    if self.Cache[key] then
        return self.Cache[key]
    end

    local png = self:BuildPng(r, g, b, mask)
    self.Cache[key] = png
    return png
end

